import pyomo.environ as pyo

DATA = {
    "products": ["regular", "premium"],
    "profit": {
        "regular": 30,
        "premium": 180,
    },
    "cost": {
        "regular": 200,
        "premium": 447,
    },
    "budget": 250000,
    "max_units": 475,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # Sets
    model.P = pyo.Set(initialize=d["products"])

    # Decision variables: number of handbags of each type (whole, non-negative)
    model.x = pyo.Var(
        model.P,
        domain=pyo.NonNegativeIntegers,
        bounds=(0, None),
    )

    # Objective: maximize monthly profit
    def profit_rule(m):
        return sum(d["profit"][p] * m.x[p] for p in m.P)

    model.obj = pyo.Objective(rule=profit_rule, sense=pyo.maximize)

    # Constraint: monthly manufacturing cost within budget
    def budget_rule(m):
        return sum(d["cost"][p] * m.x[p] for p in m.P) <= d["budget"]

    model.budget_con = pyo.Constraint(rule=budget_rule)

    # Constraint: at most the cap number of handbags of either type per month
    def units_rule(m):
        return sum(m.x[p] for p in m.P) <= d["max_units"]

    model.units_con = pyo.Constraint(rule=units_rule)

    return model


